from datetime import date


def days_between(first, second):
    pass

exercises.solution:
from datetime import date


def days_between(first, second):
    return (date.fromisoformat(second) - date.fromisoformat(first)).days

import re


def find_numbers(text):
    return re.findall(r"\d+", text)
